// Shared native command vocabulary and branch-preserving authoring. Signed: President.
#pragma once
#include "documents.hpp"
#include "scoped_state.hpp"
#include <algorithm>
#include <numeric>
namespace ps::authoring {
struct CommandSpec {const char* op;const char* label;const char* group;const char* reference;bsl::EventOp native;};
inline const std::vector<CommandSpec>& event_operations(){static const std::vector<CommandSpec> commands={
 {"set_switch","Control Switches","State","switch",bsl::EventOp::set_switch},{"set_variable","Set Variable","State","variable",bsl::EventOp::set_variable},{"add_variable","Add to Variable","State","variable",bsl::EventOp::add_variable},
 {"grant_item","Change Items: Give","Inventory","item",bsl::EventOp::grant_item},{"remove_item","Change Items: Remove","Inventory","item",bsl::EventOp::remove_item},{"wait_ticks","Wait","Flow","",bsl::EventOp::wait_ticks},{"if_switch","Conditional Branch: Switch","Flow","switch",bsl::EventOp::if_switch},
 {"grant_reward","Grant Registered Reward","Progression","source",bsl::EventOp::grant_reward},{"accept_quest","Accept Quest","Progression","quest",bsl::EventOp::accept_quest},{"claim_quest","Claim Quest Reward","Progression","quest",bsl::EventOp::claim_quest},
 {"buy_shop_item","Shop: Buy","Inventory","shop",bsl::EventOp::buy_shop_item},{"sell_shop_item","Shop: Sell","Inventory","shop",bsl::EventOp::sell_shop_item},{"advance_calendar","Advance Calendar","World","",bsl::EventOp::advance_calendar},
 {"spawn_character","Spawn Player Character","World","character",bsl::EventOp::spawn_character},{"spawn_actor","Spawn Actor Template","World","actor",bsl::EventOp::spawn_actor},{"grant_skill","Grant Registered Ability","Progression","ability",bsl::EventOp::grant_skill},{"revoke_skill","Revoke Registered Ability","Progression","ability",bsl::EventOp::revoke_skill}};return commands;}
inline const CommandSpec* command_spec(const std::string& op){for(auto& c:event_operations())if(op==c.op)return &c;return nullptr;}
inline void event_text(const Json& j,const char* key){if(!j.contains(key)||!j[key].is_string())throw std::runtime_error(std::string(key)+": text required");auto& s=j[key].get_ref<const std::string&>();if(s.size()>65536||s.find('\0')!=s.npos)throw std::runtime_error(std::string(key)+": invalid text");}
inline void command_shape(const Json& c){if(!c.is_object())throw std::runtime_error("Command must be an object");event_text(c,"op");auto op=c["op"].get<std::string>();if(!command_spec(op))throw std::runtime_error("Unsupported command: "+op);for(auto* key:{"target","offer","receipt"})if(c.contains(key))event_text(c,key);
 for(auto* key:{"value","ticks","quantity","skip","x","y"})if(c.contains(key)){if(op=="set_switch"&&std::string(key)=="value"){if(!c[key].is_boolean())throw std::runtime_error("Switch value must be boolean");}else scoped_integer(c,key);}if(c.contains("equals")&&!c["equals"].is_boolean())throw std::runtime_error("Condition equals must be boolean");}
inline std::vector<Json> event_rows(const Json& j){event_text(j,"id");event_text(j,"name");if(!j.contains("commands")||!j["commands"].is_array()||j["commands"].empty()||j["commands"].size()>256)throw std::runtime_error("Events require1–256 commands");std::vector<Json> rows;for(auto& c:j["commands"]){command_shape(c);rows.push_back(c);}return rows;}
inline void event_rows(Json& j,const std::vector<Json>& rows){Json next=j;next["commands"]=rows;event_rows(next);j.swap(next);}
struct EventRow {Json command;int source=-1;bool original=false;};
inline void event_rebuild(Json& j,const std::vector<EventRow>& order){
 auto before=event_rows(j);if(order.empty()||order.size()>256)throw std::runtime_error("Events require1–256 commands");std::vector<int> mapping(before.size(),-1);for(int i=0;i<int(order.size());++i)if(order[i].original){if(order[i].source<0||order[i].source>=int(before.size())||mapping[order[i].source]>=0)throw std::runtime_error("Invalid command mapping");mapping[order[i].source]=i;}
 std::vector<Json> after;for(int i=0;i<int(order.size());++i){auto c=order[i].command;command_shape(c);if(c["op"]=="if_switch"&&order[i].source>=0){auto old=order[i].source;int skip=scoped_integer(before.at(old),"skip");int64_t destination=int64_t(old)+1+skip;if(skip<1||destination>int64_t(before.size()))throw std::runtime_error("Fix the invalid conditional target before changing sequence order");int target=destination==int64_t(before.size())?int(order.size()):mapping.at(size_t(destination));if(target<0)throw std::runtime_error("A conditional targets the removed command; retarget it first");if(target<=i+1)throw std::runtime_error("This edit would create a backward or empty conditional branch; retarget it first");c["skip"]=target-i-1;}after.push_back(std::move(c));}event_rows(j,after);
}
inline std::vector<EventRow> event_order(const Json& j){auto rows=event_rows(j);std::vector<EventRow> order;for(int i=0;i<int(rows.size());++i)order.push_back({rows[i],i,true});return order;}
inline void event_insert(Json& j,size_t at,const Json& command){auto order=event_order(j);if(at>order.size())throw std::runtime_error("Command index out of range");command_shape(command);order.insert(order.begin()+at,{command,-1,false});event_rebuild(j,order);}
inline void event_duplicate(Json& j,size_t at){auto order=event_order(j);if(at>=order.size())throw std::runtime_error("Command index out of range");auto copy=order[at];copy.original=false;order.insert(order.begin()+at+1,std::move(copy));event_rebuild(j,order);}
inline void event_erase(Json& j,size_t at){auto order=event_order(j);if(at>=order.size())throw std::runtime_error("Command index out of range");order.erase(order.begin()+at);event_rebuild(j,order);}
inline void event_move(Json& j,size_t from,size_t to){auto order=event_order(j);if(from>=order.size()||to>=order.size())throw std::runtime_error("Command index out of range");auto row=order[from];order.erase(order.begin()+from);order.insert(order.begin()+to,std::move(row));event_rebuild(j,order);}
inline Json command_defaults(const std::string& op,const std::string& target="",const std::string& offer=""){if(!command_spec(op))throw std::runtime_error("Unsupported command");Json c={{"op",op}};if(!target.empty())c["target"]=target;if(op=="set_switch")c["value"]=true;else if(op=="if_switch"){c["equals"]=true;c["skip"]=1;}else if(op=="wait_ticks")c["ticks"]=1;else if(op=="grant_item"||op=="remove_item"||op=="buy_shop_item"||op=="sell_shop_item"){c["quantity"]=1;if(op=="buy_shop_item"||op=="sell_shop_item")c["offer"]=offer;}else if(op=="grant_reward")c["receipt"]="authored/reward";else if(op=="spawn_actor"||op=="spawn_character"){c["x"]=0;c["y"]=0;}else if(op=="advance_calendar")c["value"]=1;else if(op=="set_variable"||op=="add_variable")c["value"]=0;return c;}
inline void event_replace(Json& j,size_t at,const Json& command){auto rows=event_rows(j);if(at>=rows.size())throw std::runtime_error("Command index out of range");auto extras=rows[at];for(auto* key:{"op","target","value","equals","skip","ticks","quantity","receipt","offer","x","y"})extras.erase(key);for(auto i=command.begin();i!=command.end();++i)extras[i.key()]=i.value();rows[at]=std::move(extras);event_rows(j,rows);}
}
